import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>你有一部 iPhone，你的大多数照片就是 HEIC 文件，不管你想不想要。它们在手机上看起来完美无缺，到了半数电脑和网站上却打不开。</p>\n<p>把 HEIC 转成 JPG 就是解决办法。JPG 哪里都能打开，从十年前的 Windows 笔记本到政府上传表格，转换只要几秒钟。</p>\n<p>这篇指南讲清 HEIC 是什么、苹果为什么用它，以及怎样干净地转换，不丢掉你在意的照片。</p>\n<h2 id=\"what-is-heic\">什么是 HEIC？</h2>\n<p>HEIC 是基于 HEIF 容器的照片格式，用现代压缩存储图像。苹果从 iOS 11 开始，把它作为 iPhone 相机的默认格式。</p>\n<p>它能以大约 JPG 一半的体积存下同样的画质。正是这种高效，让你的 iPhone 能装下比 JPG 时代多一倍的照片。</p>\n<p>HEIC 文件还能在同一个文件里装额外数据，比如深度信息、连拍序列，以及让实况照片“动”起来的短视频片段。</p>\n<p>问题是兼容性。苹果体系之外，很多程序、网站和打印机根本不认识 HEIC，文件被拒时连个解释都没有。</p>\n<h2 id=\"why-iphones-use-heic\">iPhone 为什么把照片存成 HEIC？</h2>\n<p>苹果改用 HEIC 是为了省存储空间。现在的手机照片很大，每张文件减半，意味着能多装一倍的回忆。</p>\n<p>这种格式还支持 JPG 做不到的功能，比如 16 位颜色、透明背景、一个文件装多张图片。实况照片和人像景深都靠它。</p>\n<p>苹果设备原生处理 HEIC，iPhone 用户平时几乎注意不到格式的存在。问题只在照片离开苹果生态时才出现。</p>\n<p>你可以在相机设置里改成存 JPG，但大多数人从来不改。默认是 HEIC，默认就是大多数照片的样子。</p>\n<h2 id=\"why-windows-rejects-heic\">Windows 电脑为什么打不开 HEIC？</h2>\n<p>Windows 默认不带 HEIC 解码器。“照片”应用可能会提示下载解码器，但很多用户根本看不到这个提示，文件直接打不开。</p>\n<p>老软件更糟。HEIC 出现之前做的 Office 版本、邮件客户端、上传表单，根本不知道这是什么文件，直接拒绝。</p>\n<p>网站情况不一。有些现代网站接受 HEIC，但大多数上传表单只列 JPG 和 PNG，HEIC 文件直接被退回。</p>\n<p>转成 JPG 能彻底去掉这个问题。JPG 三十年来哪里都能用，这段时间里做的系统都不会拒绝它。</p>\n<h2 id=\"how-decoding-works\">浏览器里的 HEIC 解码是怎么完成的？</h2>\n<p>浏览器本身解不了 HEIC，所以转换器会在浏览器标签页里加载一个小型 WebAssembly 解码器。这个解码器读取 HEIC 容器，把照片渲染出来。</p>\n<p>解码在你的设备上进行，用的是你的处理器。标准的 1200 万像素照片解码只要一两秒，4800 万像素的 ProRAW 文件会稍久一点。</p>\n<p>解码后，照片被画到画布上，导出成标准的 JPG、PNG 或 WebP。结果就是一张任何程序都能打开的普通图片文件。</p>\n<p>整个过程没有服务器参与。你的照片从不离开设备，照片里有家人、旅行或证件时，这一点很重要。</p>\n<h2 id=\"quality-setting-90\">为什么默认画质是 90%</h2>\n<p>HEIC 转 JPG 工具默认用 90% 的 JPG 画质。这个设置是有意为之，因为它能保留让 iPhone 照片好看的细节。</p>\n<p>HEIC 文件很高效，低画质转 JPG 等于扔掉原文件辛苦保留的细节。90% 的 JPG 能让照片看起来还是它自己。</p>\n<p>低设置能省空间，但对在意的照片来说，省下的空间很少值得。一档从 90% 降到 80%，文件小了一半，精细细节却明显变软了。</p>\n<p>照片要交给有大小限制的表格时，只在必要时降低画质。从 90 开始，看大小，再逐步下调。</p>\n<h2 id=\"file-size-after-conversion\">转好的 JPG 为什么比 HEIC 大</h2>\n<p>转好的 JPG 几乎总是比原来的 HEIC 大，常常大一倍。这让很多人惊讶，但完全正常、符合预期。</p>\n<p>HEIC 是比 JPG 更高效的格式。从现代格式回到老格式要付出空间代价，因为 JPG 没法用更少的字节装下同样的细节。</p>\n<p>JPG 并没有比 HEIC 差。它装的是同一张照片，只是存得没那么高效。更大的体积是通用兼容性的代价。</p>\n<p>体积太大成问题时，转换后用压缩工具处理。85% 画质的 JPG 比 95% 的小得多，看起来依然干净。</p>\n<h2 id=\"live-photos\">实况照片会怎么样？</h2>\n<p>实况照片是一张静态图加一段存放在同一个 HEIC 文件里的短视频。转换器会把静态图导出成 JPG，丢掉视频动效。</p>\n<p>大多数用途下这是正确的行为。表格、网站、打印要的是静态照片，不是一段三秒视频。</p>\n<p>想保留动效就别转换实况照片。从“照片”应用里分享它，视频部分才能留下来。</p>\n<p>选中的静态帧是关键照片，就是你打开实况照片时看到的那一帧。它是这段短片里最好的一帧。</p>\n<h2 id=\"orientation-and-colour\">方向、颜色与分辨率</h2>\n<p>转换时方向会保留。竖版照片还是竖版，横版照片还是横版，因为转换器会读取 HEIC 文件里的方向数据。</p>\n<p>分辨率也会保留。4032×3024 的 HEIC 会变成 4032×3024 的 JPG，转换中不丢任何像素。</p>\n<p>广色域 Display P3 的颜色会转成 JPG 的标准颜色。变化很轻微，大多数照片看起来一样，只是特别饱和的颜色可能显得不那么鲜艳。</p>\n<p>GPS 位置标签会在转换中被清除，因为画到画布上会去掉 EXIF 元数据。在网上分享照片时，这能保护你的隐私。</p>\n<h2 id=\"batch-converting-albums\">整本相册一次转换</h2>\n<p>可以把整个旅行相册扔进转换器，下载一个 ZIP。每张 HEIC 用同样的设置转成 JPG，批量汇总会显示总体积。</p>\n<p>每个文件独立转换，一张坏图不会拖垮整本相册。损坏的 HEIC 显示错误标记，其余文件照常完成。</p>\n<p>每张文件最大接受 25MB，标准的 1200 万、2400 万、4800 万像素 iPhone 照片都没问题，不用任何准备。</p>\n<p>转换后留着 HEIC 原文件。它们是你手里画质最好的副本，以后需要别的格式还能再转。</p>\n<h2 id=\"heic-vs-heif\">HEIC 和 HEIF 有什么区别？</h2>\n<p>HEIF 是容器格式，HEIC 是其中用 HEVC 视频压缩存图像数据的版本。实际使用中，iPhone 照片就是扩展名为 .heic 的 HEIC 文件。</p>\n<p>有些文件用 .heif 扩展名。转换器两种都接受、同样处理，因为照片的底层结构是一样的。</p>\n<p>不用重命名文件，也不用纠结扩展名。拖进文件，解码器会处理它是哪种变体。</p>\n<p>日常使用中，这两个词意思相同：一种苹果照片格式，在大多数地方能打开之前需要先转换。</p>\n<h2 id=\"stop-future-heic\">让以后的照片不再存成 HEIC</h2>\n<p>在 iPhone 上打开“设置”，再点“相机”，再点“格式”。选“最兼容”，以后的照片就会存成 JPG，而不是 HEIC。</p>\n<p>代价是存储空间。JPG 照片大约占 HEIC 两倍的地方，相机胶卷会更快装满。</p>\n<p>大多数人还是留着 HEIC、需要时再转更好。省下的空间是实实在在的，转换也只要几秒钟。</p>\n<p>经常和 Windows 用户分享照片时，换成 JPG 能省掉所有人的转换步骤。按最常收到你照片的人来决定。</p>\n<h2 id=\"common-problems\">常见问题与解决办法</h2>\n<p>文件报“无效的 HEIC”错误，可能是文件损坏了，或者根本不是真正的 HEIC。先在 iPhone 上打开它，确认它是一张有效照片。</p>\n<p>解码很慢，文件很可能是 4800 万像素的 ProRAW 照片。这类文件携带的数据比标准照片多得多，给解码器多留几秒钟。</p>\n<p>转好的 JPG 看起来发灰，检查一下颜色。Display P3 的颜色在转换中会轻微偏移，在任何修图应用里稍微调高饱和度就能恢复冲击力。</p>\n<p>网站要求 JPG 在 100KB 以下时，先转换、再压缩。<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB 压缩工具</a>能把转好的 JPG 缩到符合要求。</p>\n<h2 id=\"sharing-with-family\">和家人分享 iPhone 照片</h2>\n<p>家人用的设备五花八门，HEIC 照片在很多设备上打不开。用旧 Windows 笔记本的长辈打不开你刚发去的照片，这一刻就错过了。</p>\n<p>分享之前先把照片转成 JPG。JPG 在任何设备上都能打开，从十年前的笔记本到最新款手机，谁都不用安装东西。</p>\n<p>家庭相册整批转换，一次分享 ZIP，或者把 JPG 上传到共享相册。不管用什么设备，每个人看到的都是同样的照片。</p>\n<p>家庭照片的画质保持在 90%。人脸保持锐利，颜色保持浓郁，文件也小到能发邮件或聊天。</p>\n<p>分享后把 HEIC 原文件留在手机上。它们是画质最好的副本，别的家人需要别的格式时还能再转。</p>\n<h2 id=\"heic-in-work-documents\">工作文档里的 HEIC 照片</h2>\n<p>工作文档常常需要一张照片，HEIC 文件贴进 Word 或 PowerPoint 可能会失败。文档在你的 Mac 上看起来没问题，在同事的 Windows 电脑上就坏了。</p>\n<p>加进文档之前，先把照片转成 JPG。JPG 能干净地嵌进 Word、PowerPoint 和 Google 文档，文档在哪里打开都正常。</p>\n<p>报告里照片很多时，先整批转换，再搭建文档。这个顺序能避免辛苦几小时后才发现一半图片坏了的挫败。</p>\n<p>转换后检查文件大小。二十张 4MB 的 JPG 放在报告里就是 80MB，可能超过邮件限制，文档要发邮件时先压缩图片。</p>\n<p>打印报告时，画质保持在 90% 或更高。打印会暴露屏幕看不出的瑕疵，高画质 JPG 是纸上最安全的选择。</p>\n<h2 id=\"printing-iphone-photos\">打印 iPhone 照片</h2>\n<p>打印店要的是 JPG 或 PNG，HEIC 文件可能直接被拒。下单打印之前先转成 JPG，并先看清打印店的要求。</p>\n<p>打印用的画质保持在 90% 或更高。6×4 英寸的照片需要每个像素的细节，低画质 JPG 在纸上的瑕疵会露出来。</p>\n<p>打印前检查尺寸。4032×3024 的 iPhone 照片印 13×10 英寸很漂亮，但裁剪过的版本可能需要更小的打印尺寸。</p>\n<p>印大幅面时，用完整分辨率的 HEIC 原文件做转换源头。从缩略图转出来的 JPG 再怎么调画质，印出来也不会锐利。</p>\n<p>重要照片先印一张测试。先印一张小的，确认颜色和锐利度，再决定大订单或画布打印。</p>\n<h2 id=\"moving-to-new-phone\">换新手机时迁移照片</h2>\n<p>换新手机是最能体现 HEIC 兼容性问题的时刻。从 iPhone 传到安卓手机的 HEIC 照片，不转换可能显示不出来。</p>\n<p>转移之前先把照片转成 JPG。JPG 在任何安卓手机、任何 Windows 电脑、任何云服务上都能打开，不用特殊软件。</p>\n<p>整个相机胶卷要转时，每批五十到一百张。批量运行顺畅，一批出问题也不会影响其他批次。</p>\n<p>迁移之前，把 HEIC 原文件备份到 iCloud 或电脑上。转移出问题时，原文件是安全的，还能再转。</p>\n<p>迁移后在新手机上抽查几张照片。打开它们，确认显示正常，再检查日期和位置有没有保留下来。</p>\n<p>准备好转换了吗？打开<a href=\"/zh/heic-zhuan-jpg/\">HEIC 转 JPG 工具</a>，把照片拖进去。想看分步操作，请读<a href=\"/zh/blog/ruhe-ba-heic-zhuancheng-jpg/\">如何把 HEIC 转换成 JPG</a>；完整对比请看<a href=\"/zh/blog/heic-vs-jpg/\">HEIC 和 JPG 有什么区别</a>。要转换很多种格式的话，<a href=\"/zh/zhuanhuan-tupian/\">图片格式转换工具</a>也能处理混合批量。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Windows 电脑上能把 HEIC 转成 JPG 吗？","answer":"可以。在 Chrome 或 Edge 这类现代 Windows 浏览器里打开转换器，拖入 HEIC 文件就行。解码在浏览器标签页里运行，Windows 本身永远不需要理解 HEIC。转好的 JPG 正常下载，任何 Windows 程序都能打开。"},{"question":"HEIC 转 JPG 会损失照片画质吗？","answer":"会损失一点，因为 JPG 是比 HEIC 更有损的格式，但 90% 画质下，正常观看时损失看不见。照片保持完整分辨率，屏幕上看起来一样。只有逐像素检查才能发现差别。"},{"question":"iPhone 上能直接把 HEIC 照片转成 JPG 吗？","answer":"可以。在 iPhone 的 Safari 或 Chrome 里打开转换器，点上传区域，从相机胶卷里选照片。转换在手机上运行，JPG 会下载到“文件”应用里。不用额外装应用。"},{"question":"HEIC 转 JPG 最好的画质设置是多少？","answer":"90% 是默认值，也是大多数照片最好的选择。它保留精细细节，文件大小也合理。只有文件大小限制逼着你时才降到 80%，并且留着 HEIC 原文件，以后还能再转。"},{"question":"HEIC 转 JPG 会去掉照片的位置信息吗？","answer":"会的。把照片画到画布上会清除 EXIF 元数据，包括 GPS 坐标、相机型号和拍摄时间。转好的 JPG 不记录照片在哪里、什么时候拍的，在网上分享更安全。"},{"question":"HEIC 文件能转成 PNG 而不是 JPG 吗？","answer":"可以，工具也提供 PNG 和 WebP 输出。PNG 是无损的，能精确保留解码后的像素，但文件比 JPG 大得多。只有需要透明背景或打算反复编辑图片时才用 PNG。"}];
